import type { Endpoint } from 'payload'

import type { CanSelfEnroll } from '../types.js'

import { checkRole } from '../access/checkRole.js'
import { enrollUser, SELF_ENROLL_ACCESS_MODES } from '../services/enrollUser.js'
import { findDoc, getSlugs, LMSError } from '../services/shared.js'
import { lmsHandler, requireId } from './handler.js'

const messages = {
  'already-completed': 'You have already completed this course.',
  'already-enrolled': 'You are already enrolled in this course.',
  'already-renewed': 'This purchase has already been applied.',
  enrolled: 'Successfully enrolled in course.',
  renewed: 'Your access has been renewed.',
}

/**
 * Self-enrollment for the logged-in user in open or free courses. Paid and group enrollments
 * must go through the server-side `enrollUser` service after the purchase is verified.
 */
export const enrollHandler = (_args?: Record<string, unknown>): Endpoint['handler'] =>
  lmsHandler(async ({ data, req, userId }) => {
    const courseId = requireId(data, 'courseId')
    if (data.isGroup) {
      throw new LMSError('Group enrollment requires a purchase.', 403)
    }

    const course = await findDoc(req, getSlugs(req).courses, courseId, 'Course')
    const isAdmin = checkRole(['admin'], req.user)
    // Unpublished courses are not enrollable; answer as if they do not exist
    if (course._status === 'draft' && !isAdmin) {
      throw new LMSError('Course not found.', 404)
    }
    const accessMode = course.enrollment?.accessMode ?? 'open'
    if (!isAdmin) {
      const canSelfEnroll = req.payload.config.custom?.lms?.canSelfEnroll as CanSelfEnroll | undefined
      // The site's check runs only after the built-in one, so it can refuse but never allow more
      if (
        !SELF_ENROLL_ACCESS_MODES.includes(accessMode) ||
        (canSelfEnroll && (await canSelfEnroll({ course, req, user: req.user! })) !== true)
      ) {
        throw new LMSError('This course requires a purchase.', 403)
      }
    }

    const { status } = await enrollUser({ courseId: course.id, req, userId })
    return Response.json({ message: messages[status], status, success: status === 'enrolled' })
  })
